scala
import org.apache.spark.sql.execution.command.CacheTableCommand
import org.apache.spark.sql.execution.CacheManager

def cacheTable(spark: SparkSession, tableName: String): Unit = {
  val catalog = spark.sessionState.catalog
  val tableIdentifier = TableIdentifier(tableName)

  if (!catalog.tableExists(tableIdentifier)) {
    throw new NoSuchTableException(s"Table $tableName does not exist.")
  }

  val table = catalog.getTableMetadata(tableIdentifier)
  val cacheManager = spark.sharedState.cacheManager

  cacheManager.cacheQuery(Dataset.ofRows(spark, table), tableIdentifier)
}

