scala
import org.apache.spark.sql.execution.command.cache.CacheManager

def cacheTable(spark: SparkSession, tableName: String): Unit = {
  val catalog = spark.sessionState.catalog
  val tableIdentifier = TableIdentifier(tableName)

  if (!catalog.tableExists(tableIdentifier)) {
    throw new NoSuchTableException(tableIdentifier.unquotedString)
  }

  val relation = catalog.lookupRelation(tableIdentifier)
  val cacheManager = spark.sharedState.cacheManager

  if (cacheManager.isCached(relation)) {
    println(s"Table $tableName is already cached.")
  } else {
    cacheManager.cacheQuery(relation, true)
    println(s"Table $tableName has been cached successfully.")
  }
}

