import java.io.InputStream
import java.nio.ByteBuffer
import org.apache.gearpump.streaming.hadoop.HadoopCheckpointStoreReader

class HadoopCheckpointStoreReader(inputStream: InputStream) {

  private val buffer = ByteBuffer.allocate(1024)

  def readNext(): Option[Array[Byte]] = {
    try {
      buffer.clear()
      val bytesRead = inputStream.read(buffer.array())
      if (bytesRead == -1) {
        None
      } else {
        Some(buffer.array().take(bytesRead))
      }
    } catch {
      case e: EOFException => None
      case e: Exception =>
        e.printStackTrace()
        None
    }
  }

  def close(): Unit = {
    inputStream.close()
  }
}

