import org.scalatest.flatspec.AnyFlatSpec
import org.scalatest.matchers.should.Matchers

class AppengineConfigFactorySpec extends AnyFlatSpec with Matchers {

  "AppengineConfigFactory" should "load configuration correctly" in {
    val filterConfig = mock[FilterConfig]
    when(filterConfig.getInitParameter("configFile")).thenReturn("test-config.xml")

    val configLoader = new ConfigLoader(filterConfig)
    val appengineConfig = AppengineConfigFactory.create(configLoader)

    appengineConfig should not be null
    appengineConfig.someSetting shouldEqual "expectedValue"
  }

  it should "throw an exception for missing configuration" in {
    val filterConfig = mock[FilterConfig]
    when(filterConfig.getInitParameter("configFile")).thenReturn(null)

    val configLoader = new ConfigLoader(filterConfig)

    assertThrows[IllegalArgumentException] {
      AppengineConfigFactory.create(configLoader)
    }
  }
}

