    def drawFaces(image: Mat, faces: Seq[Rect]): Mat = {
      faces.foreach { face =>
        Imgproc.rectangle(image, face.tl(), face.br(), new Scalar(255, 0, 0), 2)
      }
      image
    }

    def saveImage(image: Mat, path: Path): Unit = {
      Imgcodecs.imwrite(path.toString, image)
    }

    def detectAndDrawFaces(image: Mat, outputPath: Path): Unit = {
      val faces = detectFaces(image)
      val imageWithFaces = drawFaces(image, faces)
      saveImage(imageWithFaces, outputPath)
    }
  }
}

