scala
  "Customer Sqoop Export" should {
    "export data to the target database" in {
      val exportPath = "/path/to/export"
      val targetTable = "customer_table"

      // Setup the connection pool
      ConnectionPool.singleton("jdbc:mysql://localhost:3306/testdb", "user", "password")

      // Execute the Sqoop export
      SqoopExecutionTest.export(exportPath, targetTable) { implicit session =>
        SQL("SELECT COUNT(*) FROM customer_table").map(_.long(1)).single.apply().get
      } should be > 0L
    }
  }

scala
  "CustomerSqoopExport" should {
    "export data to the target table" in {
      val expectedCount = 1000
      val exportPath = "/path/to/export"
      val targetTable = "customer_table"

      // Execute the Sqoop export
      SqoopExecutionTest.executeExport(exportPath, targetTable)

      // Validate the count of records in the target table
      val actualCount = SQL(s"SELECT COUNT(*) FROM $targetTable").map(_.long("count")).single.apply().get
      actualCount shouldEqual expectedCount
    }
  }

scala
  def executeSqoopExport() = {
    val config = Map(
      "sqoop.export.dir" -> "/path/to/export",
      "sqoop.export.table" -> "customers",
      "sqoop.export.batch.size" -> "1000"
    )

    val result = SqoopExecutionTest.runExport(config)

    result match {
      case Right(success) =>
        assert(success, "Sqoop export should succeed")
      case Left(error) =>
        fail(s"Sqoop export failed with error: $error")
    }
  }

