  def connected(connector: ActorRef): Receive = {
    case QueryCommand(viewName, params) =>
      val request = HttpRequest(HttpMethods.GET, couchApiBase.withPath(Uri.Path(s"/$bucket/_design/$viewName/_view/$viewName")).withQuery(params))
      val pipeline: Future[HttpResponse] = sendReceive(connector)(request)
      pipeline.onComplete {
        case Success(response) => sender() ! response
        case Failure(exception) => log.error("Failed to fetch view: {}", exception.getMessage)
      }
  }

  private def sendReceive(connector: ActorRef)(request: HttpRequest): Future[HttpResponse] = {
    import spray.client.pipelining._
    val pipeline = sendReceive(connector)
    pipeline(request)
  }

