        val jobData = new JobData(info)
        // Process the job data as needed
        updateJobMetrics(jobData)
        renderJobPage(jobData)
      case None =>
        logWarning(s"Job with ID $jobId not found.")
        renderErrorPage(s"Job with ID $jobId not found.")
    }

