    case L.LIGD      ⇒ Some(LIGD.foldl(list2)(0)(_ + _))
    case L.HLIGD     ⇒ Some(HLIGD.foldl(list2)(0)(_ + _))
    case L.EMGM      ⇒ Some(EMGM.sum(list2))
    case L.Shapeless ⇒ Some(ShapelessFun.sum(list2))
    case _           ⇒ None
  }

