    System.gc()
    System.gc()
    val result = scalameterConfig measure { a }
    if (result >= 1)
      ("%.1f ms".format(result))
    else
      ("%.1f μs".format(result * 1000.0))
  }

  object L extends Enumeration {
    type L = Value
    val Direct, None, Shapeless, LIGD, HLIGD, EMGM = Value
  }

  val tests = List(
    ("company", company _),
    ("geq", geq _),
    ("min", min _),
    ("sum", sum _)
  )

  def main(args: Array[String]) {
    printf("\\begin{tabular}{c")
    for (lib ← tests) {
      printf("|r")
    }
    printf("}\n")
    printf("%-10s", "\\bf{test}")
    for ((testname, test) ← tests) {
      printf(" & %-15s", "\\bf{" + testname + "}")
    }
    println("\\\\")
    println("\\hline")
    for (lib ← L.values) {
      if (lib != L.None) {
        var line = "%-10s".format(lib.toString())
        for ((testname, test) ← tests) {
          test(lib) match {
            case Some(result) ⇒ assert(result == test(L.None).get, s"${lib.toString}: $testname failed. Expected ${test(L.None)}, received ${test(lib)}")
            case None         ⇒ true
          }

          line += bench(lib.toString(), testname, test(lib))
        }
        print(line)
        println("\\\\")
      }
    }
    println("\\end{tabular}")
  }

}

