  def findMaterialDeterminationById(id: ObjectUUID): FutureMusitResult[Option[MaterialDetermination]] = {
    val action = {
      for {
        eventOpt <- findEventById(id)
        materialInfoOpt <- eventOpt match {
          case Some(event) => getSpecialAttributes(event.id).map(Some(_))
          case None => DBIO.successful(None)
        }
      } yield materialInfoOpt.map(materialInfo => MaterialDetermination(eventOpt.get, Some(materialInfo)))
    }
    daoUtils.dbRun(
      action,
      s"An unexpected error occurred fetching MaterialDetermination for id $id"
    )
  }

