  private var interpreter: IMain = _
  private var lastEvaluation: Option[SimpleEvaluationObject] = None
  private var resetState: ResetState = ResetState("initial")

  def initialize(): Unit = {
    val settings = new Settings
    settings.usejavacp.value = true
    interpreter = new IMain(settings, new JLineCompletion)
  }

  def evaluate(code: String, evaluationObject: SimpleEvaluationObject): Unit = {
    lastEvaluation = Some(evaluationObject)
    val result = interpreter.interpret(code)

    result match {
      case Success => evaluationObject.setSuccess("Evaluation successful")
      case Error(msg) => evaluationObject.setError(msg)
      case _ => evaluationObject.setError("Unknown evaluation result")
    }
  }

  def reset(): Unit = {
    interpreter.reset()
    resetState = ResetState("reset")
    lastEvaluation.foreach(_.setSuccess("Interpreter reset"))
  }

  def complete(code: String, cursor: Int): List[String] = {
    val completions = interpreter.completions(code, cursor)
    completions.map(_.completion).toList
  }
}

