package org.sparkline.utils

object PartitionUtils {

  def partitionData[T](data: Seq[T], partitions: Int): Seq[Seq[T]] = {
    require(partitions > 0, "Number of partitions must be greater than zero.")

    val partitionSize = Math.ceil(data.size.toDouble / partitions).toInt
    data.grouped(partitionSize).toSeq
  }
}

